    var mt = try std.fmt.allocPrint(galloc, "{}", .{max_tokens});
    defer galloc.free(mt);
    try body.appendSlice(mt);
    try body.appendSlice("}}");

    const base = "";
    var url_builder = std.ArrayList(u8).init(galloc);
    defer url_builder.deinit();
    try url_builder.appendSlice(base);
    try url_builder.appendSlice(full_path);
    const full_url = try url_builder.toOwnedSlice();

    const headers_extra = [_]HeaderKV{};
    return try httpPostJson(full_url, headers_extra[0..], body.items);
}

