    var tmp = messagesJsonAppendAssistant(galloc, messages, full.items) catch messages;
    galloc.free(messages);
    messages = tmp;

    if (p.cerebras) |cb2| {
        const out = cerebrasChat(cb2, "gpt-oss-120b", messages, 48000, 0.6, 0.7, true) catch null;
        if (out) |o| { _ = full.appendSlice(o) catch {}; galloc.free(o); }
    }
    tmp = messagesJsonAppendAssistant(galloc, messages, full.items) catch messages;
    galloc.free(messages);
    messages = tmp;

    if (p.cerebras) |cb3| {
        const out = cerebrasChat(cb3, "glm-4.6", messages, 20000, 0.3, 0.4, false) catch null;
        if (out) |o| { _ = full.appendSlice(o) catch {}; galloc.free(o); }
    }
    tmp = messagesJsonAppendAssistant(galloc, messages, full.items) catch messages;
    galloc.free(messages);
    messages = tmp;

    if (p.openai) |oai| {
        const out = openaiChat(oai, "gpt-4.1", messages, 36000, 0.4, 0.5) catch null;
        if (out) |o| { _ = full.appendSlice(o) catch {}; galloc.free(o); }
    }
    tmp = messagesJsonAppendAssistant(galloc, messages, full.items) catch messages;
    galloc.free(messages);
    messages = tmp;

    if (p.anthropic) |a| {
        const out = anthropicChat(a, "claude-3-opus-20240229", sys, messages, 36000, 0.4) catch null;
        if (out) |o| { _ = full.appendSlice(o) catch {}; galloc.free(o); }
    }
    tmp = messagesJsonAppendAssistant(galloc, messages, full.items) catch messages;
    galloc.free(messages);
    messages = tmp;

    if (p.gemini) |g| {
        const mapped = geminiMapContents(galloc, sys, messages) catch null;
        if (mapped) |m| {
            const out = geminiGenerate(g, "models/gemini-2.5-pro", m, 0.4, 0.5, 36000) catch null;
            if (out) |o| { _ = full.appendSlice(o) catch {}; galloc.free(o); }
            galloc.free(m);
        }
    }
    tmp = messagesJsonAppendAssistant(galloc, messages, full.items) catch messages;
    galloc.free(messages);
    messages = tmp;

    if (p.xai) |x| {
        const out = xaiChat(x, "grok-2-mini", messages, 36000, 0.5, 0.6) catch null;
        if (out) |o| { _ = full.appendSlice(o) catch {}; galloc.free(o); }
    }

    while (full.items.len < target_chars) {
        const cont = continueTailPrompt(galloc, full.items, 2000) catch break;
        defer galloc.free(cont);
        var m2 = messagesJsonSystemUser(galloc, sys, cont) catch break;
        defer galloc.free(m2);
        if (p.cerebras) |cb| {
