            if (out) |o| { _ = full.appendSlice(o) catch {}; galloc.free(o); }
        } else break;
        if (full.items.len >= target_chars) break;
    }
    return full.toOwnedSlice() catch full.items;
}

fn deriveQueriesOutline(alloc: std.mem.Allocator, seed: []const u8) !struct { queries: [][]u8, outline: [][]u8 } {
    var queries = std.ArrayList([]u8).init(alloc);
    var outline = std.ArrayList([]u8).init(alloc);
    var it = std.mem.tokenizeAny(u8, seed, " .,;:\n\r\t");
    var seen = std.StringHashMap(void).init(alloc);
    while (it.next()) |tok| {
        if (tok.len > 5 and tok.len < 64) {
            if (!seen.contains(tok)) {
                var cp = try std.mem.alloc(u8, tok.len);
                std.mem.copy(u8, cp, tok);
                _ = try seen.put(cp, {});
                try queries.append(cp);
                if (queries.items.len >= 30) break;
            }
        }
    }
    try outline.append(try std.mem.dupe(alloc, u8, "Executive Summary"));
    try outline.append(try std.mem.dupe(alloc, u8, "Background"));
    try outline.append(try std.mem.dupe(alloc, u8, "Methods"));
    try outline.append(try std.mem.dupe(alloc, u8, "Findings"));
    try outline.append(try std.mem.dupe(alloc, u8, "Discussion"));
    try outline.append(try std.mem.dupe(alloc, u8, "Conclusion"));
    try outline.append(try std.mem.dupe(alloc, u8, "References"));
    return .{ .queries = queries.toOwnedSlice(), .outline = outline.toOwnedSlice() };
}

fn runJob(id: []const u8, seed: []const u8, url_hint_opt: ?[]const u8, target_chars: usize, max_sources: usize, prov: Providers) void {
    var st = JobState{ .status = "starting", .progress = 0, .started_at = nowTs(), .finished_at = 0, .queries_count = 0, .urls_count = 0 };
    if (jobs.get(id)) |jp| jp.*.state = st;

    const deriv = deriveQueriesOutline(galloc, seed) catch {
        if (jobs.get(id)) |jp| {
            jp.*.state.status = "error";
            jp.*.state.finished_at = nowTs();
        }
        return;
    };
    st.status = "searching";
    st.progress = 5;
    st.queries_count = deriv.queries.len;
    if (jobs.get(id)) |jp| jp.*.state = st;

    const urls = gatherSources(prov.exa, deriv.queries, 25, max_sources) catch std.ArrayList([]u8).init(galloc);
    st.status = "fetching";
    st.progress = 15;
    st.urls_count = urls.items.len;
    if (jobs.get(id)) |jp| jp.*.state = st;

    const docs = fetchDocs(urls.items, 120000) catch std.ArrayList([]u8).init(galloc);
    st.progress = 30;
    if (jobs.get(id)) |jp| jp.*.state = st;

    var summaries = std.ArrayList([]u8).init(galloc);
    var count: usize = 0;
    const cap = if (docs.items.len < 200) docs.items.len else 200;
    while (count < cap) : (count += 1) {
        const s = summarizeDocAll(prov, docs.items[count], if (count < urls.items.len) urls.items[count] else "");
        _ = summaries.append(s) catch {};
        const p = 30 + @min(40, @as(u8, @intCast((count * 40) / @max(1, cap))));
        st.progress = p;
        if (jobs.get(id)) |jp| jp.*.state = st;
    }

    st.status = "composing";
    if (jobs.get(id)) |jp| jp.*.state = st;

    const report = composeReport(prov, deriv.outline, summaries.items, target_chars);
    var refs = std.ArrayList(u8).init(galloc);
    _ = refs.appendSlice("{\"queries\":[") catch {};
    for (deriv.queries, 0..) |q, qi| {
        if (qi > 0) _ = refs.appendSlice(",") catch {};
        const esc = jsonEscape(galloc, q) catch q;
        _ = refs.appendSlice("\"") catch {};
        _ = refs.appendSlice(esc) catch {};
        _ = refs.appendSlice("\"") catch {};
        if (esc.ptr != q.ptr) galloc.free(esc);
    }
    _ = refs.appendSlice("],\"urls\":[") catch {};
    for (urls.items, 0..) |u, ui| {
        if (ui > 0) _ = refs.appendSlice(",") catch {};
        const escu = jsonEscape(galloc, u) catch u;
        _ = refs.appendSlice("\"") catch {};
        _ = refs.appendSlice(escu) catch {};
        _ = refs.appendSlice("\"") catch {};
        if (escu.ptr != u.ptr) galloc.free(escu);
    }
    _ = refs.appendSlice("]}") catch {};
    const sources_json = refs.toOwnedSlice() catch refs.items;

    var prefix = std.ArrayList(u8).init(galloc);
    _ = prefix.appendSlice("# Research Report\n\n") catch {};
    const report_md = blk: {
        _ = prefix.appendSlice(report) catch {};
        _ = prefix.appendSlice("\n\n# References\n\n") catch {};
        for (urls.items) |u| {
            _ = prefix.appendSlice("- ") catch {};
            _ = prefix.appendSlice(u) catch {};
            _ = prefix.appendSlice("\n") catch {};
        }
        break :blk prefix.toOwnedSlice() catch prefix.items;
    };

    if (jobs.get(id)) |jp| {
        jp.*.result = .{ .report = report_md, .sources_json = sources_json };
        jp.*.state.status = "done";
        jp.*.state.progress = 100;
        jp.*.state.finished_at = nowTs();
    }
}

fn handleRoot(res: *Response) !void {
    var file = std.fs.cwd().openFile("index.html", .{}) catch {
        res.status = .ok;
        try res.headers.append("content-type", "text/html; charset=utf-8");
        try res.send();
        try res.writeAll("<!doctype html><html><body>jadedlight</body></html>");
        return;
    };
    defer file.close();
    const st = try file.stat();
    var data = try galloc.alloc(u8, @intCast(st.size));
    _ = try file.readAll(data);
    res.status = .ok;
    try res.headers.append("content-type", "text/html; charset=utf-8");
    try res.send();
    try res.writeAll(data);
    galloc.free(data);
}

fn handleStart(res: *Response, prov: Providers) !void {
    var body = try res.reader().readAllAlloc(galloc, 50 * 1024 * 1024);
    defer galloc.free(body);
    const ct = res.request.headers.getFirstValue("content-type") orelse "";

    var seed_text: []u8 = "";
    var url_hint: []u8 = "";
    var target_chars: usize = 500000;
    var max_sources: usize = 1000;

    if (std.mem.startsWith(u8, ct, "multipart/form-data")) {
        var mp = try parseMultipart(galloc, body, ct);
        defer {
            var it = mp.iterator();
            while (it.next()) |e| galloc.free(e.value_ptr.*);
            mp.deinit();
        }
        if (mp.get("file")) |v| {
            seed_text = try std.mem.dupe(galloc, u8, v);
        }
        if (mp.get("url")) |v| {
            url_hint = try std.mem.dupe(galloc, u8, v);
        }
        if (mp.get("target_chars")) |v| {
            target_chars = std.fmt.parseInt(usize, v, 10) catch target_chars;
        }
        if (mp.get("max_sources")) |v| {
            max_sources = std.fmt.parseInt(usize, v, 10) catch max_sources;
        }
    } else if (std.mem.startsWith(u8, ct, "application/x-www-form-urlencoded")) {
        var fm = try urlencodedToMap(galloc, body);
        defer {
            var it = fm.iterator();
            while (it.next()) |e| {
                galloc.free(e.key_ptr.*);
                galloc.free(e.value_ptr.*);
            }
            fm.deinit();
        }
        if (fm.get("url")) |v| url_hint = try std.mem.dupe(galloc, u8, v);
        if (fm.get("target_chars")) |v| target_chars = std.fmt.parseInt(usize, v, 10) catch target_chars;
        if (fm.get("max_sources")) |v| max_sources = std.fmt.parseInt(usize, v, 10) catch max_sources;
    } else {
        res.status = .bad_request;
        try res.send();
        return;
    }

    if (seed_text.len == 0 and url_hint.len > 0) {
        const fetched = httpGetText(url_hint) catch "";
        if (fetched.len > 0) seed_text = try std.mem.dupe(galloc, u8, fetched);
        if (fetched.len > 0) galloc.free(fetched);
    }
    if (seed_text.len == 0 and url_hint.len == 0) {
        res.status = .bad_request;
        try res.headers.append("content-type", "application/json");
        try res.send();
        try res.writeAll("{\"detail\":\"input required\"}");
        return;
    }

    var norm = seed_text;
    if (norm.len > 20000) {
        const cp = try galloc.alloc(u8, 20000);
        std.mem.copy(u8, cp, norm[0..20000]);
        norm = cp;
    }

    var rand_bytes: [16]u8 = undefined;
    std.crypto.random.bytes(&rand_bytes);
    const id = std.fmt.allocPrint(galloc, "{s}", .{std.fmt.fmtSliceHexLower(rand_bytes[0..])}) catch blk: {
        const fallback = "job";
        break :blk try std.mem.dupe(galloc, u8, fallback);
    };

    var job = try galloc.create(Job);
    job.* = .{
        .id = id,
        .state = .{ .status = "queued", .progress = 0, .started_at = nowTs(), .finished_at = 0, .queries_count = 0, .urls_count = 0 },
        .result = null,
    };
    try jobs.put(id, job);

    const prov_captured = prov;
    _ = std.Thread.spawn(.{}, struct {
        fn f(ctx: struct { id: []const u8, seed: []const u8, url_hint: ?[]const u8, target: usize, maxs: usize, p: Providers }) void {
            runJob(ctx.id, ctx.seed, ctx.url_hint, ctx.target, ctx.maxs, ctx.p);
        }
    }.f, .{ .id = id, .seed = norm, .url_hint = if (url_hint.len > 0) url_hint else null, .target = target_chars, .maxs = max_sources, .p = prov_captured }) catch {};

    res.status = .ok;
    try res.headers.append("content-type", "application/json; charset=utf-8");
    try res.send();
    try res.writeAll("{\"job_id\":\"");
    try res.writeAll(id);
    try res.writeAll("\"}");
}

fn handleStatus(res: *Response) !void {
    const path = res.request.target;
    const base = "/research/status/";
    if (path.len <= base.len or !std.mem.startsWith(u8, path, base)) {
        res.status = .bad_request;
        try res.send();
        return;
    }
    const job_id = path[base.len..];
    const j = jobs.get(job_id) orelse {
        res.status = .not_found;
        try res.send();
        return;
    };
    res.status = .ok;
    try res.headers.append("content-type", "application/json; charset=utf-8");
    try res.send();
    var buf = std.ArrayList(u8).init(galloc);
    defer buf.deinit();
    try buf.appendSlice("{\"status\":\"");
    try buf.appendSlice(j.*.state.status);
    try buf.appendSlice("\",\"progress\":");
    try buf.writer().print("{}", .{j.*.state.progress});
    try buf.appendSlice(",\"started_at\":");
    try buf.writer().print("{}", .{j.*.state.started_at});
    try buf.appendSlice(",\"finished_at\":");
    try buf.writer().print("{}", .{j.*.state.finished_at});
    try buf.appendSlice(",\"queries\":");
    try buf.writer().print("{}", .{j.*.state.queries_count});
    try buf.appendSlice(",\"urls\":");
    try buf.writer().print("{}", .{j.*.state.urls_count});
    try buf.appendSlice("}");
    const out = try buf.toOwnedSlice();
    defer galloc.free(out);
    try res.writeAll(out);
}

fn handleSSE(res: *Response) !void {
    const path = res.request.target;
    const base = "/research/stream/";
    if (path.len <= base.len or !std.mem.startsWith(u8, path, base)) {
        res.status = .bad_request;
        try res.send();
        return;
    }
    const job_id = path[base.len..];
    const j = jobs.get(job_id) orelse {
        res.status = .not_found;
        try res.send();
        return;
    };
    res.status = .ok;
    try res.headers.append("content-type", "text/event-stream");
    try res.headers.append("cache-control", "no-cache");
    try res.headers.append("connection", "keep-alive");
    try res.send();

    while (true) {
        const s = j.*.state;
        var payload = std.ArrayList(u8).init(galloc);
        defer payload.deinit();
        try payload.appendSlice("data: ");
        var json = std.ArrayList(u8).init(galloc);
        defer json.deinit();
        try json.appendSlice("{\"status\":\"");
        try json.appendSlice(s.status);
        try json.appendSlice("\",\"progress\":");
        try json.writer().print("{}", .{s.progress});
        try json.appendSlice(",\"started_at\":");
        try json.writer().print("{}", .{s.started_at});
        try json.appendSlice(",\"finished_at\":");
        try json.writer().print("{}", .{s.finished_at});
        try json.appendSlice("}");
        const js = try json.toOwnedSlice();
        defer galloc.free(js);
        try payload.appendSlice(js);
        try payload.appendSlice("\n\n");
        const pl = try payload.toOwnedSlice();
        defer galloc.free(pl);
        try res.writeAll(pl);
        if (std.mem.eql(u8, s.status, "done")) break;
        std.time.sleep(1_000_000_000);
    }
}

fn handleDownload(res: *Response) !void {
    const path = res.request.target;
    const base = "/download/";
    if (!std.mem.startsWith(u8, path, base)) {
        res.status = .bad_request;
        try res.send();
        return;
    }
    const name_with_ext = path[base.len..];
    const job_id = if (std.mem.endsWith(u8, name_with_ext, ".zip"))
        name_with_ext[0 .. name_with_ext.len - 4]
    else
        name_with_ext;

    const j = jobs.get(job_id) orelse {
        res.status = .not_found;
        try res.send();
        return;
    };
    if (j.*.result == null) {
        res.status = .not_found;
        try res.send();
        return;
    }

    res.status = .ok;
    try res.headers.append("content-type", "text/markdown; charset=utf-8");
    var cd = try std.fmt.allocPrint(galloc, "attachment; filename=\"{s}.md\"", .{job_id});
    defer galloc.free(cd);
    try res.headers.append("content-disposition", cd);
    try res.send();
    try res.writeAll(j.*.result.?.report);
}

fn getenvOwned(name: []const u8) ?[]u8 {
    return std.process.getEnvVarOwned(galloc, name) catch null;
}

fn loadProviders() Providers {
    var p = Providers{
        .cerebras = null,
        .openai = null,
        .anthropic = null,
        .gemini = null,
        .xai = null,
        .exa = null,
    };

    if (getenvOwned("CEREBRAS_API_KEY")) |v| {
        p.cerebras = CerebrasCfg{ .api_key = v };
    }
    if (getenvOwned("OPENAI_API_KEY")) |v| {
        p.openai = OpenAIcfg{ .api_key = v };
    }
    if (getenvOwned("ANTHROPIC_API_KEY")) |v| {
        p.anthropic = AnthropicCfg{ .api_key = v };
    }
    if (getenvOwned("GEMINI_API_KEY")) |v| {
        p.gemini = GeminiCfg{ .api_key = v };
    }
    if (getenvOwned("XAI_API_KEY")) |v| {
        p.xai = XAIcfg{ .api_key = v };
    }
    if (getenvOwned("EXA_API_KEY")) |v| {
        p.exa = ExaCfg{ .api_key = v };
    }

    return p;
}

fn handleHttp(res: *Response, prov: Providers) !void {
    const method = res.request.method;
    const target = res.request.target;

    if (method == .GET and std.mem.eql(u8, target, "/")) {
        try handleRoot(res);
        try res.finish();
        return;
    }
    if (method == .POST and std.mem.eql(u8, target, "/research/start")) {
        try handleStart(res, prov);
        try res.finish();
        return;
    }
    if (method == .GET and std.mem.startsWith(u8, target, "/research/status/")) {
        try handleStatus(res);
        try res.finish();
        return;
    }
    if (method == .GET and std.mem.startsWith(u8, target, "/research/stream/")) {
        try handleSSE(res);
        try res.finish();
        return;
    }
    if (method == .GET and std.mem.startsWith(u8, target, "/download/")) {
        try handleDownload(res);
        try res.finish();
        return;
    }

    res.status = .not_found;
    try res.headers.append("content-type", "text/plain; charset=utf-8");
    try res.send();
    try res.writeAll("404 Not Found");
    try res.finish();
}

